package fraymus.workspace;
import org.json.*;
import java.util.*;
final class RecordedReport162 {
 static JSONArray cells(JSONObject w){var s=w.getJSONObject("source162");var r=s.getJSONObject("region");var d=w.getJSONObject("definition");return new JSONArray().put(s.getJSONObject("binding").getString("trialId")).put(s.getInt("ordinal")).put(s.getJSONObject("frame").getString("imageSha256")).put(r.getJSONArray("center").toString()).put(r.getJSONArray("min").toString()).put(r.getJSONArray("max").toString()).put(s.getDouble("coordinateRadiusM")).put(d.getDouble("executionToleranceM")).put(d.getDouble("maxTotalErrorM"));}
 static JSONObject build(JSONObject w,JSONObject child){var base=SmallReport161.build(child);var cells=cells(w);String[] names={"Recorded trial","Frame ordinal","Original image SHA256","Projected X/Z centre (m)","Region minimum X/Z (m)","Region maximum X/Z (m)","Coordinate radius (m)","Execution allowance (m)","Combined allowance (m)"};var table=new StringBuilder("<section><h2>Recorded object → simulated proxy</h2><p id='scope162'>"+RecordedSmall162.LIMIT+"</p><table id='source162'><tbody>");for(int i=0;i<names.length;i++)table.append("<tr><th style='text-align:left;padding:8px'>").append(names[i]).append("</th><td style='overflow-wrap:anywhere'>").append(cells.get(i)).append("</td></tr>");table.append("</tbody></table></section>");var files=base.getJSONObject("files");files.put("index.html",files.getString("index.html").replace("</h1>","</h1>"+table).replace("<title>Single-object motion ·161</title>","<title>Recorded object workflow ·162</title>").replace("FRAYNIX · EDITION161","FRAYNIX · EDITION162"));files.put("recorded-source.json",MapCheckpoint.canonical(new JSONObject().put("source",w.getJSONObject("source162")).put("plan",w.getJSONObject("plan162"))));base.put("title","Recorded object · verified simulation");return base;}
 static JSONObject audit(JSONObject w,JSONObject child,JSONObject observed){var cells=cells(w);var actual=observed.getJSONArray("cells162");if(actual.length()!=cells.length()||!observed.getBoolean("visible162")||!observed.getString("scope162").equals(RecordedSmall162.LIMIT))throw new IllegalStateException("Recorded uncertainty evidence hidden or changed");for(int i=0;i<cells.length();i++)if(!actual.getString(i).equals(cells.get(i).toString()))throw new IllegalStateException("Rendered recorded coordinate or budget changed");SmallReport161.audit(child,observed.getJSONObject("motion"));var nativeAudit=SmallReport161.audit(child,observed.getJSONObject("nativeMotion"));if(child.has("audit")&&!child.getJSONObject("audit").similar(nativeAudit))throw new IllegalStateException("Original native acknowledgement changed");return new JSONObject().put("passed",true).put("observed",observed).put("sourceSha256",WorldFrames.hash(w.getJSONObject("source162")));}
}
